WITH scored AS (SELECT *, LAST_VALUE(sqft, TRUE) OVER (PARTITION BY region ORDER BY opened_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_sqft, DENSE_RANK() OVER w_ordered AS sqft_dense_rank, COUNT(sqft) OVER w_grp AS region_count_sqft, LAG(sqft, 2, 0) OVER (PARTITION BY city ORDER BY opened_date, id) AS prev_sqft, CUME_DIST() OVER (ORDER BY sqft NULLS LAST) AS sqft_cume_dist FROM stores WINDOW w_ordered AS (PARTITION BY city ORDER BY sqft DESC NULLS FIRST), w_grp AS (PARTITION BY region, city)) SELECT city, DATE_TRUNC('QUARTER', opened_date) AS quarter_start, BIT_AND(sqft) AS sqft_bit_and, ROUND(SUM(sqft_cume_dist) / NULLIF(COUNT(CASE WHEN city = 'Bangkok' THEN 1 END), 0), 2) AS sqft_cume_dist_per_bangkok FROM scored GROUP BY GROUPING SETS ((city, DATE_TRUNC('QUARTER', opened_date)), (city)) ORDER BY quarter_start DESC NULLS FIRST;
